using System;using System.IO;using System.Linq;using System.Web.Script.Serialization;using CrownWorkshop;
class ModeTests {
static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;}
static void Main(string[] args){for(int index=0;index<2;index++){var bytes=File.ReadAllBytes(args[index]);var s=new WorkshopSession();s.Load(args[index]);Check(s.Save.Mode==(index==0?"Retro":"Classic"),"Content mode");Check(s.Save.Render().SequenceEqual(bytes),"No-op identical");var model=new JavaScriptSerializer().Serialize(s.State());Check(model.Contains("\"mode\":\""+s.Save.Mode+"\""),"Model mode");Check(s.Save.Entities.Select(e=>e.Label).Distinct().Count()==s.Save.Entities.Count,"Unique labels");foreach(var e in s.Save.Entities.Where(e=>e.Has("Garrison"))){var region=s.Save.Entities.Single(x=>x.Has("Region")&&x.Id==e.Number("RegionId"));Check(region.Number("GarrisonId")==e.Id,"Region garrison link");Check(s.Owner(e)==s.Owner(region),"Garrison owner");Check(s.Role(e)=="Garrison","Garrison role");}foreach(var f in s.Save.Fields.Where(f=>f.Editable&&new[]{"Gold","Soldiers","Knights","Catapults","Leadership","Jousting","Swordplay"}.Contains(f.Name))){int id=s.Save.Fields.IndexOf(f);s.Set(id,"123",false);Check(new Save(s.Save.Render()).Fields[id].Original=="123","Readback "+f.Name);s.Undo();Check(s.Save.Render().SequenceEqual(bytes),"Undo exact");}Check(File.ReadAllBytes(args[index]).SequenceEqual(bytes),"Live file untouched");}
var list=Desktop.Discover(args[2]);Check(list.Any(x=>x.mode=="Retro"),"Retro discovered");Check(list.Any(x=>x.mode=="Classic"&&!x.autosave),"Named Classic discovered");Check(list.Any(x=>x.mode=="Classic"&&x.autosave),"Classic autosave discovered");Check(!list.Any(x=>x.path.EndsWith("metadata.sav")||x.path.Contains("Backups")),"Metadata and backups excluded");Console.WriteLine("PASS: "+n+" mode, garrison, discovery, edit and preservation checks; no save writes.");}}
